userscript.function:

if(Sepoa.info.MASTER_COMPANY_FLAG == 'Y' && Sepoa.info.MENU_PROFILE_CODE == Sepoa.config.get('sepoa.system.manager.profile.code')){
	filterObj.setShow('AFFILIATED_COMPANY');
} else{
	filterObj.setHide('AFFILIATED_COMPANY');
	dataOutput.setValue('COMPANY_CODE', Sepoa.info.COMPANY_CODE, true);
}
dataOutput.addFilter(filterObj);
gridObj.postConnection(window.CONTEXT_NAME + '/SepoaGrid.sux', ['mode=doQuery', 'PROCESS_ID=sepoa.svc.admin.SepoaOrgManagementService', 'METHOD=doQueryCtrlManagerGrid']);
gridObj.clearAll(false);


// 결재자 강제세팅(사용인감모듈) || (법인인감모듈) 이 True일때
if (sUtils.workflow.check('USW1673407285901') || sUtils.workflow.check('CSW1673407570340')) {
    appConfirm_val = true;
} else {
    appConfirm_val = false;
}


var msg = obj.getUserData("", "message");
if (rowCnt == 0) {
    Alert(Sepoa.cache.text.get('MESSAGE.1001'));
    return;
} else if (msg) {
    Alert(msg);
}

// init에서 모듈확인후 True일경우 결제순서 hidden으로 변경하는 소스
if (appConfirm_val) {
    gridObj.setColumnHidden(gridObj.getColIndexById('APP_ORDER'), false);
} else {
    gridObj.setColumnHidden(gridObj.getColIndexById('APP_ORDER'), true);
}


var mode = obj.mode;
var status = obj.status;
var message = obj.message;
if (status == 'true') {
    Alert(message);
    doQuery();
} else {
    Alert(message);
}


            var header = gridObj.getColumnId(cInd);
            var selectedCompanyCode = gridObj.cells(rId, gridObj.getColIndexById('COMPANY_CODE')).getValue();
            if (stage == 0) {
                if (header == 'APP_ORDER' && gridObj.cells(rId, gridObj.getColIndexById('CTRL_CODE')).getValue() != 'APP_CONFIRM') {
                    return false;
                }
            } else if (stage == 2) {
                // 결제순서 중복 검사
                if (header == 'APP_ORDER') {
                    var serId = rId;
                    if(!sUtils.string.isBlank(selectedCompanyCode)){
	                	var rows = [];
	                	for(let i = 1; i<=gridObj.getRowsNum(); i++){
	                		if(selectedCompanyCode == gridObj.cells(i, gridObj.getColIndexById('COMPANY_CODE')).getValue()){
	                			rows.push(i);
	                		}
	                	}
	                    for(let row of rows) {
	                    	var appOrderVal = gridObj.cells(row, gridObj.getColIndexById('APP_ORDER')).getValue();
	                        var ctrlCode = gridObj.cells(row, gridObj.getColIndexById('CTRL_CODE')).getValue();
	                        if (serId != row && appOrderVal == nValue && ctrlCode == 'APP_CONFIRM') {
	                            Alert("결재 순서는 중복될 수 없습니다.");
	                            gridObj.cells(serId, gridObj.getColIndexById('APP_ORDER')).setValue('');
	                            gridObj.cells(serId, gridObj.getColIndexById('SELECTED')).setValue(false);
	                            return false;
	                        }
	                    }
	                }
                }

                // 동일직무를 가진 담당자 검사
                if (header == 'CTRL_CODE') {
                	if(!sUtils.string.isBlank(selectedCompanyCode)){
                		var rows = [];
	                	for(let i = 1; i<=gridObj.getRowsNum(); i++){
	                		if(selectedCompanyCode == gridObj.cells(i, gridObj.getColIndexById('COMPANY_CODE')).getValue()){
	                			rows.push(i);
	                		}
	                	}
	                	for(let row of rows) {
	                        var ctrlCode = gridObj.cells(row, gridObj.getColIndexById('CTRL_CODE')).getValue();
	                        var person_Id = gridObj.cells(rId, gridObj.getColIndexById('CTRL_PERSON_ID')).getValue();
	                        var person_Id_order = gridObj.cells(row, gridObj.getColIndexById('CTRL_PERSON_ID')).getValue();
	                        if (rId != row && ctrlCode == nValue && person_Id == person_Id_order) {
	                            Alert("동일한 직무를 가진 담당자가 있습니다.");
	                            gridObj.cells(rId, gridObj.getColIndexById('CTRL_CODE')).setValue('');
	                            gridObj.cells(rId, gridObj.getColIndexById('SELECTED')).setValue(false);
	                            return false;
	                        }
	                    }
                	} else{
	                	Alert('회사를 선택해주세요.');
	                	return;
	                }
                }
            }
            return true;


var header = gridObj.getColumnId(cInd);
selectedRowId = rId;

if (header == 'CTRL_PERSON_ID' || header == 'CTRL_PERSON_NAME') {
    if (gridObj.cells(rId, gridObj.getColIndexById('COMPANY_CODE')).getValue() == '') {
        Alert("회사명을 선택해주세요.");
    } else if (gridObj.cells(rId, gridObj.getColIndexById('CTRL_CODE')).getValue() == '') {
        Alert("직무를 선택해주세요.");
    } else {
        PopupCommonPost('SL0056', setCtrlPerson, [Sepoa.info.HOUSE_CODE, gridObj.cells(rId, gridObj.getColIndexById('COMPANY_CODE')).getValue()]);
    }
} else if (header == 'CTRL_NAME_LOC') {
    PopupCommonPost('AD1024', setCtrlCode, [Sepoa.info.HOUSE_CODE, gridObj.cells(rId, gridObj.getColIndexById('COMPANY_CODE')).getValue()]);
} else if (header == 'COMPANY_CODE') {
    if (Sepoa.info.MASTER_COMPANY_FLAG == 'Y' && Sepoa.info.MENU_PROFILE_CODE == Sepoa.config.get('sepoa.system.manager.profile.code')) {
        PopupCommonPost('AD1020_4', popupCallback, [Sepoa.info.HOUSE_CODE]);
    } else {
        PopupCommonPost('AD1020_5', popupCallback, [Sepoa.info.HOUSE_CODE, Sepoa.info.COMPANY_CODE]);
    }
}

gridObj.cells(rId, gridObj.getColIndexById('SELECTED')).setValue(true);


//사용인감결재자강제지정 && 법인인감결재자강제지정 
if (!sUtils.workflow.check('USW1673407285901') && !sUtils.workflow.check('CSW1673407570340')) {
    if (ctrlCode == 'APP_CONFIRM') {
        Alert('결재자 직무를 사용할 수 없는 상태입니다. 모듈설정을 확인해주세요');
        return;
    }
}

gridObj.cells(selectedRowId, gridObj.getColIndexById('CTRL_TYPE')).setValue(ctrlType);
gridObj.cells(selectedRowId, gridObj.getColIndexById('CTRL_CODE')).setValue(ctrlCode);
gridObj.cells(selectedRowId, gridObj.getColIndexById('CTRL_NAME_LOC')).setValue(ctrlName);

var header = gridObj.cells(selectedRowId, gridObj.getColIndexById('CTRL_TYPE')).getValue();
if (header != 'APP_CONFIRM') {
    gridObj.cells(selectedRowId, gridObj.getColIndexById('APP_ORDER')).setValue('');
}


            let falseYN;
            doServiceAjax('sepoa.svc.admin.SepoaOrgManagementService', 'CONNECTION', 'doCheckUser', {
                PERSON_ID: id,
                COMPANY_CODE: companyCode
            }, function(so) {
                if (so.status == 1) {
                    var sf = new SepoaFormater(so.result[0]);
                    if (sf.getValue('CNT', 0) > 0) {} else {
                        Alert("사용자 정보가 존재하지 않습니다. 다시 선택해주세요");
                        gridObj.cells(selectedRowId, gridObj.getColIndexById('CTRL_PERSON_NAME')).setValue('');
                        gridObj.cells(selectedRowId, gridObj.getColIndexById('CTRL_PERSON_ID')).setValue('');
                        falseYN = 'Y';
                        return false;
                    }
                } else {
                    Alert(Sepoa.cache.text.get("MESSAGE.1002")); //오류발생
                    return false;
                }
            }, false);

            if (falseYN != 'Y') {
                gridObj.forEachRowA(function(ids) {
                    if (id != ids && gridObj.cells(selectedRowId, gridObj.getColIndexById('COMPANY_CODE')).getValue() == gridObj.cells(ids, gridObj.getColIndexById('COMPANY_CODE')).getValue() &&
                        gridObj.cells(selectedRowId, gridObj.getColIndexById('CTRL_CODE')).getValue() == gridObj.cells(ids, gridObj.getColIndexById('CTRL_CODE')).getValue() &&
                        id == gridObj.cells(ids, gridObj.getColIndexById('CTRL_PERSON_ID')).getValue()
                    ) {
                        gridObj.cells(selectedRowId, gridObj.getColIndexById('CTRL_PERSON_NAME')).setValue('');
                        gridObj.cells(selectedRowId, gridObj.getColIndexById('CTRL_PERSON_ID')).setValue('');
                        Alert("직무가 동일한 담당자가 있습니다.");
                        falseYN = 'Y';
                        return;
                    }
                });

                //DB에서 중복 동일직무 담당자 검사 
                var selectedCtrlCode = gridObj.cells(selectedRowId, gridObj.getColIndexById('CTRL_CODE')).getValue();
                doServiceAjax('sepoa.svc.admin.SepoaOrgManagementService', 'CONNECTION', 'doDuplicateCtrlManager', {
                	COMPANY_CODE:companyCode,
               		CTRL_PERSON_ID:id,
               		CTRL_CODE:selectedCtrlCode
                	}, function( so ){
		                if(so.status != 1){
		                	Alert('동일한 직무담당자가 존재합니다.'); // 동일한 직무담당자가 존재합니다.
		                    gridObj.cells(rId, gridObj.getColIndexById("CTRL_PERSON_ID")).setValue(oValue);
		                    gridObj.cells(rId, gridObj.getColIndexById("CTRL_PERSON_NAME")).setValue(oValue);
		                    return;
		                }
	       		    },false);


                gridObj.cells(selectedRowId, gridObj.getColIndexById('CTRL_PERSON_ID')).setValue(id);
                if (Sepoa.info.LANGUAGE == 'KO') {
                    gridObj.cells(selectedRowId, gridObj.getColIndexById('CTRL_PERSON_NAME')).setValue(nameLoc);
                } else {
                    gridObj.cells(selectedRowId, gridObj.getColIndexById('CTRL_PERSON_ID')).setValue(id);
                }
            }


var rowCount = gridObj.getRowsNum();
var maxRowId = rowCount + 1;

gridObj.addRow(maxRowId, '', gridObj.getRowsNum());
gridObj.cells(maxRowId, gridObj.getColIndexById('SELECTED')).setValue("1");
gridObj.cells(maxRowId, gridObj.getColIndexById('REPRESENT_CTRL')).setValue("N");

gridObj.showRow(maxRowId);


if (gridObj.getGridChangedRows("SELECTED").length == 0) {
    Alert(Sepoa.cache.text.get('MESSAGE.1004'));
    return;
}

if (!gridObj.validate()) {
    Alert(Sepoa.cache.text.get('MESSAGE.0003'));
    return;
}

var result = [];
gridObj.forEachRow(function(rId) {
    var ctrlCode = gridObj.cells(rId, gridObj.getColIndexById('CTRL_CODE')).getValue();
    var appOrderVal = gridObj.cells(rId, gridObj.getColIndexById('APP_ORDER')).getValue();

    if (appOrderVal == '' && ctrlCode == 'APP_CONFIRM') {
        result.push('false');
    } else {
        result.push('true');
    }
})
if (result.indexOf('false') > -1) {
    Alert("직무가 결재자의 경우 결재 순서를 지정해주세요.");
    return;
}
Confirm(Sepoa.cache.text.get('MESSAGE.1018'), function(result) {
    if (result) {
        gridObj.editStop();
        gridObj.postTransaction(window.CONTEXT_NAME + '/SepoaGrid.sux', ['mode=doSave', 'PROCESS_ID=sepoa.svc.admin.SepoaOrgManagementService', 'METHOD=doSaveCtrlManagerGrid'], 'SELECTED');
    }
});
